/** The sheet's answer for a sorted id triple, or null if it has none. */
export function canonConfluenceFor(sortedIds) {
  if (!Array.isArray(sortedIds) || sortedIds.length !== 3) return null;
  return CONFLUENCE_CANON[sortedIds.slice().sort().join(',')] || null;
}

/** How many trios the sheet has answered. Read by the data lane, so "the CSV
 *  was emptied by accident" is a visible number rather than a silent zero. */
export const CONFLUENCE_CANON_COUNT = 371;
